fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    // Input length consistency
    verifier::assert(s2.len() == n);
    verifier::assert(s3.len() == n);

    // Preallocate result vector with capacity 3 * n
    let mut res = Vec::with_capacity(3 * n);

    let mut i = 0;
    while i < n {
        // Loop invariant: res.len() == 3*i
        verifier::invariant(res.len() == 3 * i);
        verifier::invariant(i <= n);

        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);

        i += 1;
    }

    // Postconditions about length and contents
    verifier::assert(res.len() == 3 * n);
    for i in 0..n {
        verifier::assert(res[3 * i] == s1[i]);
        verifier::assert(res[3 * i + 1] == s2[i]);
        verifier::assert(res[3 * i + 2] == s3[i]);
    }

    res
}